import { test, expect } from 'bun:test';
import { createStore } from '../src/store.js';
import { reserve } from '../src/stock.js';
test('reserve takes stock and returns what is left', async () => {
  const store = createStore({ a: 5 });
  expect(await reserve(store, 'a', 3)).toBe(2);
  expect(await store.get('a')).toBe(2);
});
test('rejects when there is not enough, stock unchanged', async () => {
  const store = createStore({ a: 2 });
  await expect(reserve(store, 'a', 3)).rejects.toThrow();
  expect(await store.get('a')).toBe(2);
});

