import { test, expect } from 'bun:test';
import { createStore } from '../src/store.js';
import { reserve } from '../src/stock.js';
test('concurrent reservations never oversell', async () => {
  const store = createStore({ a: 5 });
  const res = await Promise.allSettled(Array.from({ length: 10 }, () => reserve(store, 'a', 1)));
  expect(res.filter((r) => r.status === 'fulfilled').length).toBe(5);
  expect(res.filter((r) => r.status === 'rejected').length).toBe(5);
  expect(await store.get('a')).toBe(0);
});
test('a rejected reservation does not block later ones, other skus are independent', async () => {
  const store = createStore({ a: 1, b: 4 });
  const res = await Promise.allSettled([reserve(store, 'a', 2), reserve(store, 'b', 2), reserve(store, 'b', 2), reserve(store, 'a', 1)]);
  expect(res.map((r) => r.status)).toEqual(['rejected', 'fulfilled', 'fulfilled', 'fulfilled']);
  expect(await store.get('a')).toBe(0);
  expect(await store.get('b')).toBe(0);
});
